-- Persist category images uploaded before assets moved off Render ephemeral storage.

UPDATE "Category"
SET "imageData" = decode('', 'hex'),
    "imageMimeType" = 'image/webp',
    "imageUrl" = '/api/v1/category-images/' || "id"::text || '-c8e5c298ce247c90.webp'
WHERE "slug" = 'food-products'
  AND "imageData" IS NULL
  AND ("imageUrl" = '/api/v1/category-images/ab94ebcc-4fe0-4b49-ae08-76303da5f863.png' OR "imageUrl" IS NULL);

